<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title ?? 'School Administration') ?></title><style>
:root{--ink:#172033;--muted:#64748b;--line:#dbe2ea;--surface:#fff;--soft:#f3f6fa;--brand:#075985;--brand2:#0c4a6e;--danger:#991b1b}*{box-sizing:border-box}body{font-family:Inter,ui-sans-serif,system-ui,sans-serif;margin:0;color:var(--ink);background:var(--soft);line-height:1.5}a{color:var(--brand)}.skip-link{position:absolute;left:-9999px}.skip-link:focus{left:1rem;top:1rem;background:#fff;padding:.75rem;z-index:9}.admin-nav{display:flex;align-items:center;gap:.35rem;overflow:auto;padding:.8rem max(1rem,calc((100% - 78rem)/2));background:#0f172a}.admin-nav a{color:#e2e8f0;text-decoration:none;padding:.55rem .7rem;border-radius:.4rem;white-space:nowrap}.admin-nav a:hover,.admin-nav a:focus{background:#334155;color:#fff}.admin-main{max-width:78rem;margin:auto;padding:1.4rem}.page-head{margin-bottom:1.25rem}.page-head h1{font-size:clamp(1.7rem,4vw,2.4rem);margin:.1rem 0}.page-head p{color:var(--muted);margin:.2rem 0}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:.75rem;font-weight:800;color:var(--brand)!important}.panel{padding:1.15rem;background:var(--surface);border:1px solid var(--line);border-radius:.75rem;box-shadow:0 2px 8px #0f172a0a}.panel h2{margin-top:0}.admin-grid,.split-grid,.metric-grid,.action-grid{display:grid;gap:1rem}.admin-grid{grid-template-columns:repeat(auto-fit,minmax(19rem,1fr))}.split-grid{grid-template-columns:repeat(auto-fit,minmax(20rem,1fr))}.metric-grid{grid-template-columns:repeat(auto-fit,minmax(8rem,1fr));margin-bottom:1rem}.metric{background:#fff;border:1px solid var(--line);border-radius:.7rem;padding:1rem}.metric strong{display:block;font-size:1.7rem}.metric span,.muted,small{color:var(--muted)}.action-grid{grid-template-columns:repeat(auto-fit,minmax(13rem,1fr))}.action-card{display:flex;flex-direction:column;text-decoration:none;padding:1rem;border:1px solid var(--line);border-radius:.6rem}.action-card:hover{border-color:var(--brand)}label{display:block;margin:.75rem 0;font-weight:650}input,textarea,select,button{font:inherit;max-width:100%;width:100%;padding:.62rem;border:1px solid #b9c4d0;border-radius:.4rem;background:#fff}textarea{min-height:6rem}button,.button{display:inline-block;width:auto;border:0;background:var(--brand);color:#fff;padding:.65rem .9rem;border-radius:.4rem;text-decoration:none;font-weight:700;cursor:pointer}.button.secondary{background:#e2e8f0;color:#172033}.check{display:flex;gap:.5rem;align-items:center}.check input{width:auto}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.notice,.error,.empty{padding:.8rem;border-radius:.5rem;margin:1rem 0}.notice{background:#ecfdf5;border:1px solid #a7f3d0}.error{background:#fef2f2;color:var(--danger);border:1px solid #fecaca}.empty{background:#f8fafc;color:var(--muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.7rem;border-bottom:1px solid var(--line);vertical-align:top}.badge{display:inline-block;background:#e2e8f0;border-radius:99px;padding:.18rem .5rem;font-size:.8rem;text-transform:capitalize}.record-list{padding:0;list-style:none}.record-list li{padding:.55rem 0;border-bottom:1px solid var(--line)}.compact-form{display:grid;grid-template-columns:minmax(7rem,.6fr) minmax(10rem,1fr) auto;gap:.4rem;align-items:center}.compact-form button{white-space:nowrap}@media(max-width:680px){.admin-main{padding:.8rem}.form-row,.compact-form{grid-template-columns:1fr}.admin-nav{padding:.6rem}.panel{padding:.9rem}table{min-width:38rem}}
</style></head><body data-layout="tenant-admin"><a class="skip-link" href="#admin-content">Skip to content</a><nav class="admin-nav" aria-label="School administration"><?php foreach(service('navigationResolver')->tenantItems() as $nav):?><a href="<?= site_url(ltrim($nav['route'],'/')) ?>"><?= esc($nav['label']) ?></a><?php endforeach?></nav><main id="admin-content" class="admin-main"><?= $this->renderSection('content') ?></main></body></html>
